{
  "rules": [
    "If sentiment is positive (≥ 0.2) in recent history, model tends to underpredict; adjust forecast upward by 1–3% for next period.",
    "If model shows steady upward trend with no recent spike, but true outcome shows sharp spike, reduce forecast slope by 5–10% to avoid overshoot.",
    "When true outcome exceeds model by >5% for 2+ consecutive days, apply mean reversion: next forecast = previous true + 0.5×(true - model).",
    "If sentiment is negative (≤ 0.0) and model is flat or rising, reduce forecast by 2–5% to account for downward bias.",
    "For 30-day horizon, if model is consistently above true outcome by >10% over 5+ days, apply downward correction: subtract 0.5×(model - true) from next forecast.",
    "If sentiment history shows increasing positivity (e.g., 0.0 → 0.2 → 0.4), model often overcorrects; reduce forecast slope by 10–15% to avoid lagged overreaction."
  ]
}
